#
# Copy result JSON/JSONL and RESULTS.md back from the instance. Deliberately
# does NOT copy results/cache/ -- those are multi-gigabyte embedding and logit
# dumps that are regenerated by re-running, and they are gitignored anyway.
#
# The .jsonl include is the ARI-D reference passes, which are the deliverable
# of that session rather than a cache: ~120 KB per pass, and regenerating one
# means relaunching a multi-GPU node. Response transcripts stay excluded --
# those are the dry run's, they live in S3, and the manifest binds them by
# digest.
#
# Usage: ./fetch_results.sh <instance-ip> [key-path]
set -euo pipefail

IP="${1:?usage: fetch_results.sh <instance-ip> [key-path]}"
# Key pairs are per-region, so launch.sh names them per-region too. Track that
# default here rather than pointing at a path that belongs to another region.
REGION="${AWS_REGION:-us-east-1}"
KEY="${2:-$HOME/.ssh/semq-ari-gpu-${REGION}.pem}"
DEST="$(cd "$(dirname "$0")/.." && pwd)"

echo "==> fetching results from $IP"
rsync -avz --progress \
  -e "ssh -i $KEY -o StrictHostKeyChecking=accept-new" \
  --include='*/' \
  --include='results/*.json' \
  --include='results/*.jsonl' \
  --include='RESULTS.md' \
  --exclude='results/cache/**' \
  --exclude='results/transcripts/**' \
  --exclude='*' \
  "ubuntu@$IP:semq-ari-benchmark/experiments/" \
  "$DEST/experiments/"

echo
echo "==> changed files"
git -C "$DEST" status --short experiments/ || true
echo
echo "Review the diff before committing. A GPU run that silently produced the"
echo "same numbers as the CPU run means the GPU conditions did not execute."
